using System; using System.IO; using System.Linq; using System.Reflection; using System.Threading.Tasks; using System.Collections.Generic; using UnityEngine; using UnityEngine.UI; using UnityEditor; using UnityEngine.SceneManagement; using Mavis;
public static class AutoQaUiLifecycleRegression {
 const string K="AUTO_QA.UI011"; const BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;
 static object Get(object o,string f)=>o.GetType().GetField(f,F).GetValue(o);
 static void Guard(){if(!Application.isPlaying||SceneManager.sceneCount!=1||!string.IsNullOrEmpty(SceneManager.GetActiveScene().path))throw new Exception("Isolated unsaved Play required");}
 static async Task Frame(){int f=Time.frameCount;var limit=DateTime.UtcNow.AddSeconds(8);while(Time.frameCount==f){if(DateTime.UtcNow>limit)throw new Exception("Frame timeout");await Task.Delay(5);}}
 static object Write(string name,object data){File.WriteAllText("AUTO_QA/Evidence/"+name+".json",Newtonsoft.Json.JsonConvert.SerializeObject(data,Newtonsoft.Json.Formatting.Indented));return data;}
 public static async Task<object> Prepare(string take){Guard(); if(GameObject.Find("AUTO_QA UI owner"))throw new Exception("Existing fixture");SessionState.SetString(K+".Take",take);SessionState.SetFloat(K+".Time",Time.timeScale);SessionState.SetInt(K+".Cursor",(int)Cursor.lockState);SessionState.SetBool(K+".Visible",Cursor.visible);
 var go=new GameObject("AUTO_QA UI owner"); var ui=go.AddComponent<SahurLoadoutUI>(); var map=go.AddComponent<IslandMapUI>();var cameraGo=new GameObject("AUTO_QA UI camera",typeof(Camera));cameraGo.tag="MainCamera";var cam=cameraGo.GetComponent<Camera>();cam.cullingMask=12345;
 ui.SetOpen(true);bool gearOpened=ui.PanelVisible&&SahurLoadoutUI.IsOpen&&Time.timeScale==0;ui.SetOpen(false);await Frame();map.SetOpen(true);bool mapOpened=map.PanelVisible&&cam.cullingMask==0&&Time.timeScale==0;map.SetOpen(false);bool restored=cam.cullingMask==12345;await Frame();
 SessionState.SetInt(K+".Owner",go.GetInstanceID());SessionState.SetInt(K+".Camera",cameraGo.GetInstanceID());SessionState.SetInt(K+".GearRoot",((GameObject)Get(ui,"root")).GetInstanceID());SessionState.SetInt(K+".MapRoot",((GameObject)Get(map,"root")).GetInstanceID());SessionState.SetString(K+".Assembly",typeof(AutoQaUiLifecycleRegression).Assembly.GetName().Name);
 return Write(take+"-before",new{gearOpened,mapOpened,restored,frame=Time.frameCount});}
 public static async Task<object> AfterReload(bool expectHealthy){Guard();var take=SessionState.GetString(K+".Take","");var go=EditorUtility.EntityIdToObject(SessionState.GetInt(K+".Owner",0)) as GameObject;var cam=(EditorUtility.EntityIdToObject(SessionState.GetInt(K+".Camera",0)) as GameObject).GetComponent<Camera>();var ui=go.GetComponent<SahurLoadoutUI>();var map=go.GetComponent<IslandMapUI>();var rows=new List<object>();int passed=0,total=0;Action<bool,string> check=(ok,label)=>{total++;if(ok)passed++;rows.Add(new{ok,label});};
 check(!AppDomain.CurrentDomain.GetAssemblies().Any(a=>a.GetName().Name==SessionState.GetString(K+".Assembly","")),"Actual reload unloaded preparation assembly");
 ui.SetOpen(true);check(ui.PanelVisible&&SahurLoadoutUI.IsOpen,"Equipment menu reopens after reload");check(Time.timeScale==0,"Equipment menu pauses game");ui.SetOpen(false);check(Time.timeScale==SessionState.GetFloat(K+".Time",1),"Equipment close restores time");await Frame();map.SetOpen(true);check(map.PanelVisible&&IslandMapUI.IsOpen,"Map reopens after reload");check(cam.cullingMask==0,"Map suppresses world rendering");map.SetOpen(false);check(cam.cullingMask==12345,"Map close restores camera mask");await Frame();
 var oldGear=EditorUtility.EntityIdToObject(SessionState.GetInt(K+".GearRoot",0));var oldMap=EditorUtility.EntityIdToObject(SessionState.GetInt(K+".MapRoot",0));check(!oldGear || oldGear==(UnityEngine.Object)Get(ui,"root"),"No orphan equipment canvas");check(!oldMap || oldMap==(UnityEngine.Object)Get(map,"root"),"No orphan map canvas");
 ui.enabled=false;ui.enabled=true;ui.SetOpen(true);check(ui.PanelVisible,"Equipment reenable opens");ui.SetOpen(false);await Frame();map.enabled=false;map.enabled=true;map.SetOpen(true);check(map.PanelVisible,"Map reenable opens");map.enabled=false;check(!map.PanelVisible&&Time.timeScale==SessionState.GetFloat(K+".Time",1)&&cam.cullingMask==12345,"Disable open map restores world and time");map.enabled=true;
 return Write(take+"-after",new{expectHealthy,passed,total,allPassed=passed==total,rows,frame=Time.frameCount});}
 public static object Cleanup(){var go=EditorUtility.EntityIdToObject(SessionState.GetInt(K+".Owner",0)) as GameObject;if(go)UnityEngine.Object.DestroyImmediate(go);foreach(string f in new[]{"Camera","GearRoot","MapRoot"}){var o=EditorUtility.EntityIdToObject(SessionState.GetInt(K+"."+f,0));if(o)UnityEngine.Object.DestroyImmediate(o);SessionState.EraseInt(K+"."+f);}Time.timeScale=SessionState.GetFloat(K+".Time",1);Cursor.lockState=(CursorLockMode)SessionState.GetInt(K+".Cursor",0);Cursor.visible=SessionState.GetBool(K+".Visible",true);foreach(string f in new[]{"Take","Assembly"})SessionState.EraseString(K+"."+f);SessionState.EraseInt(K+".Owner");return new{cleaned=true};}
}